{
  "passageId": "audio-perceptual-coding",
  "items": [
    {
      "id": "R1",
      "type": "PROCESS",
      "otherName": "",
      "reason": "장치를 준비하고 소리를 입력한 뒤 변환·기록이 진행되는 처리 단계의 차례이므로 과정·순서에 해당한다."
    },
    {
      "id": "R2",
      "type": "CAUSE",
      "otherName": "",
      "reason": "나팔의 진동이 바늘을 움직여 그 형태에 따른 홈을 만들게 하는 실제 물리적 작용이다."
    },
    {
      "id": "R3",
      "type": "MEANS_END",
      "otherName": "",
      "reason": "판에 홈을 만드는 것이 소리를 저장하기 위한 수단으로 제시된다."
    },
    {
      "id": "R4",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "초기와 이후의 아날로그 기록에서 현재의 디지털 저장으로 시대와 설명 대상이 넘어간다."
    },
    {
      "id": "R5",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "균일한 비트 할당이라는 일반적 설명을 통상적인 할당량인 16비트로 구체화한다."
    },
    {
      "id": "R6",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "데이터 양이 많다는 사실을 이유로 압축이 필요하다는 당위적 판단을 도출한다."
    },
    {
      "id": "R7",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "압축이 필요하다는 과제에 대해 실제 이용하는 기술인 지각부호화를 해결 방법으로 제시한다."
    },
    {
      "id": "R8",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "압축에 이용한다고 소개한 지각부호화가 어떤 기술인지 그 뜻을 풀이한다."
    },
    {
      "id": "R9",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "청각 특성으로 제시된 최소가청강도의 뜻을 가청 소리 크기의 최솟값으로 정의한다."
    },
    {
      "id": "R10",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "청각 특성으로 제시된 차폐가 무엇인지 큰 소리 때문에 작은 소리가 들리지 않는 현상으로 풀이한다."
    },
    {
      "id": "R11",
      "type": "CONDITION",
      "otherName": "",
      "reason": "소리 크기가 최소가청강도보다 큰지 작은지에 따라 가청 여부가 갈리는 조건 관계이다."
    },
    {
      "id": "R12",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "최소가청강도가 주파수별로 정해진다는 설명을 특정 주파수 구간의 사례로 보여 준다."
    },
    {
      "id": "R13",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "저음에서 더 큰 소리여야 들린다는 사례로 최소가청강도의 주파수별 특성을 구체화한다."
    },
    {
      "id": "R14",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "서로 다른 주파수 구간을 들을 수 있는 최소 소리 크기라는 같은 기준으로 비교한다."
    },
    {
      "id": "R15",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "차폐 현상을 일으키는 큰 소리에 차폐음이라는 이름을 붙이고 그 뜻을 풀이한다."
    },
    {
      "id": "R16",
      "type": "CONDITION",
      "otherName": "",
      "reason": "두 소리의 주파수가 가까운지 충분히 떨어져 있는지에 따라 차폐 발생 여부가 갈린다."
    },
    {
      "id": "R17",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "주파수 차이에 따라 차폐가 발생하는 범위를 임계대역이라는 구간으로 명명하고 규정한다."
    },
    {
      "id": "R18",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "주파수에 따라 임계대역 폭이 다르다는 설명을 고음과 저음의 구체적인 비교로 풀어 준다."
    },
    {
      "id": "R19",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "가청 소리 크기의 최솟값을 조용한 상태에서 정하는 경우와 차폐를 고려해 정하는 경우로 구별한다."
    },
    {
      "id": "R20",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "청각적 성질을 이용해 압축한다는 설명을 문턱값 산출과 비트 할당·제거의 세부 절차로 구체화한다."
    },
    {
      "id": "R21",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "차폐가 가능한 주파수 구간이라는 임계대역 개념을 실제 오디오 신호의 분할에 적용한다."
    },
    {
      "id": "R22",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "최소가청강도라는 청각적 기준을 지각부호화의 차폐 문턱값 산출에 적용한다."
    },
    {
      "id": "R23",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "큰 소리가 차폐를 일으킨다는 성질을 지각부호화의 차폐 문턱값 산출에 적용한다."
    },
    {
      "id": "R24",
      "type": "PROCESS",
      "otherName": "",
      "reason": "오디오 신호를 임계대역으로 나눈 뒤 각 대역의 차폐 문턱값을 구하는 단계적 순서이다."
    },
    {
      "id": "R25",
      "type": "PROCESS",
      "otherName": "",
      "reason": "앞 단계에서 산출한 차폐 문턱값을 바탕으로 다음 단계의 비트 할당이 진행된다."
    },
    {
      "id": "R26",
      "type": "MEANS_END",
      "otherName": "",
      "reason": "문턱값과의 차이가 큰 소리에 많은 비트를 할당하는 것은 소리 손실을 낮추기 위한 수단이다."
    },
    {
      "id": "R27",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "문턱값 미만의 소리는 들리지 않는다는 사실이 그 소리를 제거하는 처리의 근거로 제시된다."
    },
    {
      "id": "R28",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "비트 수가 많을수록 원음에 가까워진다는 원리를 지각부호화의 차등 비트 할당에 적용한다."
    },
    {
      "id": "R29",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "압축 전의 균일한 할당과 지각부호화의 차등 할당을 비트 배분 방식이라는 같은 기준으로 비교한다."
    },
    {
      "id": "R30",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "감도가 낮은 소리를 제거한다는 일반적 설명을 차폐 문턱값 미만의 소리 제거로 구체화한다."
    },
    {
      "id": "R31",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "저장과 전송을 위해 압축이 필요하다는 과제에 품질 저하를 최소화하는 지각부호화 기술이 대응한다."
    }
  ]
}

